package dev.starcrownqa;
import dev.starcrown.*;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.animal.*;
import net.minecraft.world.entity.npc.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.trading.*;
import net.minecraft.world.effect.*;
import net.minecraft.world.*;
import net.minecraft.nbt.CompoundTag;
@GameTestHolder("starcrownqa") @PrefixGameTestTemplate(false)
public final class CharityTests {
 @GameTest(template="empty",timeoutTicks=100) public static void healingAndPact(GameTestHelper h){var p=ChastityTests.player(h);var cow=ChastityTests.spawn(EntityType.COW,p,2,0,0);var v=ChastityTests.spawn(EntityType.VILLAGER,p,-2,0,0);try{ChastityTests.equip(p);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);cow.setHealth(2);h.assertTrue(p.interactOn(cow,InteractionHand.MAIN_HAND).consumesAction(),"empty hand interaction consumed");h.assertTrue(cow.getHealth()==cow.getMaxHealth(),"cow fully healed");var effect=cow.getEffect(MobEffects.DAMAGE_RESISTANCE);h.assertTrue(effect!=null&&effect.getAmplifier()==4&&effect.getDuration()==1200,"Resistance V lasts60 seconds");h.assertTrue(cow.getPersistentData().getUUID(YuleCharity.PACT).equals(p.getUUID()),"animal pact established without taming");h.assertTrue(p.interactOn(v,InteractionHand.MAIN_HAND).consumesAction()&&v.getPersistentData().hasUUID(YuleCharity.PACT),"village pact bypasses trade restriction without opening trade menu");var tag=new CompoundTag();cow.saveWithoutId(tag);h.assertTrue(tag.getCompound("ForgeData").hasUUID(YuleCharity.PACT),"pact serialized with entity");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WHEAT));h.assertTrue(!YuleCharity.canUse(p,cow,p.getMainHandItem()),"nonempty hand cannot use creator hand");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);cow.getPersistentData().remove(YuleCharity.PACT);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.interactOn(cow,InteractionHand.MAIN_HAND);h.assertTrue(!cow.getPersistentData().hasUUID(YuleCharity.PACT),"unequip disables pact");h.succeed();}finally{cow.discard();v.discard();ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void sorrowCosts(GameTestHelper h){var p=ChastityTests.player(h);var cow=ChastityTests.spawn(EntityType.COW,p,2,0,0);var far=ChastityTests.spawn(EntityType.COW,p,16.1,0,0);var skeleton=ChastityTests.spawn(EntityType.SKELETON,p,3,0,0);try{ChastityTests.equip(p);p.setHealth(20);cow.setHealth(0);cow.die(p.damageSources().generic());h.assertTrue(p.getHealth()==10,"actual non-undead death halves health despite humility cap");YuleCharity.sorrow(skeleton);YuleCharity.sorrow(far);h.assertTrue(p.getHealth()==10,"undead and outside sphere do not cost health");YuleCharity.sorrow(cow);h.assertTrue(p.getHealth()==5,"each subsequent loss halves current health");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);YuleCharity.sorrow(cow);h.assertTrue(p.getHealth()==5,"unequip releases sorrow");h.succeed();}finally{cow.discard();far.discard();skeleton.discard();ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void deathItemsAndExperience(GameTestHelper h){var p=ChastityTests.player(h);var item=new ItemEntity(p.level(),p.getX(),p.getY(),p.getZ(),new ItemStack(Items.LEATHER));p.serverLevel().addFreshEntity(item);var cow=ChastityTests.spawn(EntityType.COW,p,2,0,0);try{ChastityTests.equip(p);var drops=new java.util.ArrayList<ItemEntity>();drops.add(item);YuleCharity.drops(new net.minecraftforge.event.entity.living.LivingDropsEvent(cow,p.damageSources().generic(),drops,0,false));item.setNoPickUpDelay();item.playerTouch(p);h.assertTrue(!item.isRemoved()&&item.getItem().getCount()==1,"death loot cannot be collected");h.assertTrue(!p.getInventory().add(item.getItem().copy()),"direct inventory insertion rejected");var chest=new net.minecraft.world.SimpleContainer(item.getItem().copy());var slot=new net.minecraft.world.inventory.Slot(chest,0,0,0);h.assertTrue(!slot.mayPickup(p),"container cannot launder death loot");var saved=new CompoundTag();item.saveWithoutId(saved);h.assertTrue(saved.getCompound("ForgeData").getBoolean(YuleCharity.DEATH),"death provenance persists");int xp=p.totalExperience;YuleCharity.deathExperience(p.serverLevel(),p.position(),7);var orbs=p.serverLevel().getEntitiesOfClass(ExperienceOrb.class,p.getBoundingBox().inflate(1));h.assertTrue(!orbs.isEmpty(),"death experience generated and marked");for(var orb:orbs){h.assertTrue(YuleCharity.deathLoot(orb),"death xp has provenance");orb.playerTouch(p);h.assertTrue(!orb.isRemoved()&&p.totalExperience==xp,"death xp cannot be collected");}p.takeXpDelay=0;var normal=new ExperienceOrb(p.level(),p.getX(),p.getY(),p.getZ(),3);p.serverLevel().addFreshEntity(normal);normal.playerTouch(p);h.assertTrue(p.totalExperience==xp+3,"nondeath experience remains available");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);p.takeXpDelay=0;orbs.get(0).playerTouch(p);h.assertTrue(p.totalExperience>xp+3,"unequip releases death experience");item.playerTouch(p);h.assertTrue(item.isRemoved(),"unequip releases death items");for(var orb:orbs)orb.discard();normal.discard();h.succeed();}finally{cow.discard();item.discard();ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void liveGiftsAndPause(GameTestHelper h){var p=ChastityTests.player(h);var cow=ChastityTests.spawn(EntityType.COW,p,2,0,0);var v=ChastityTests.spawn(EntityType.VILLAGER,p,-2,0,0);try{ChastityTests.equip(p);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.interactOn(cow,InteractionHand.MAIN_HAND);p.interactOn(v,InteractionHand.MAIN_HAND);var book=new ItemStack(Items.ENCHANTED_BOOK);net.minecraft.world.item.EnchantedBookItem.addEnchantment(book,new net.minecraft.world.item.enchantment.EnchantmentInstance(net.minecraft.world.item.enchantment.Enchantments.MENDING,1));var offers=new MerchantOffers();offers.add(new MerchantOffer(new ItemStack(Items.EMERALD,8),book,3,1,.05f));v.getOffers().clear();v.getOffers().addAll(offers);for(int i=0;i<19;i++)YuleCharity.produce(v);h.assertTrue(!p.getInventory().contains(Items.ENCHANTED_BOOK.getDefaultInstance()),"no gift before one second");YuleCharity.produce(v);ItemStack found=ItemStack.EMPTY;for(int i=0;i<9;i++)if(p.getInventory().getItem(i).is(Items.ENCHANTED_BOOK))found=p.getInventory().getItem(i);h.assertTrue(!found.isEmpty()&&!YuleCharity.deathLoot(found)&&found.hasTag(),"current trade product and enchantments gifted");h.assertTrue(offers.get(0).getUses()==0,"free gift does not spend trade stock");var animalGifts=YuleCharity.gifts(cow,p);h.assertTrue(animalGifts.stream().anyMatch(s->s.is(Items.BEEF)),"actual animal loot table used without death");for(var stack:animalGifts)h.assertTrue(!YuleCharity.deathLoot(stack),"live animal gift not flagged death loot");h.assertTrue(cow.isAlive()&&v.isAlive()&&p.getHealth()==20,"gifts do not kill source or trigger sorrow");v.getPersistentData().putInt(YuleCharity.CLOCK,0);p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);for(int i=0;i<25;i++)YuleCharity.produce(v);h.assertTrue(v.getPersistentData().getInt(YuleCharity.CLOCK)==0,"unequip pauses production");ChastityTests.equip(p);v.moveTo(p.getX()+17,p.getY(),p.getZ());YuleCharity.produce(v);h.assertTrue(v.getPersistentData().getInt(YuleCharity.CLOCK)==0,"outside radius pauses production");h.succeed();}finally{cow.discard();v.discard();ChastityTests.close(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void realDeathProvenance(GameTestHelper h){var p=ChastityTests.player(h);var cow=ChastityTests.spawn(EntityType.COW,p,2,0,0);var l=p.serverLevel();try{cow.tickCount=100;cow.setLastHurtByPlayer(p);cow.setHealth(0);cow.die(l.damageSources().generic());var orbs=l.getEntitiesOfClass(ExperienceOrb.class,cow.getBoundingBox().inflate(2));h.assertTrue(!orbs.isEmpty(),"actual animal death produces XP through native entry");for(var orb:orbs)h.assertTrue(YuleCharity.deathLoot(orb),"native death XP redirect preserves source");var items=l.getEntitiesOfClass(ItemEntity.class,cow.getBoundingBox().inflate(2));h.assertTrue(items.stream().anyMatch(i->i.getItem().is(Items.BEEF)),"actual animal death generates loot");for(var item:items)h.assertTrue(YuleCharity.deathLoot(item),"native death loot event preserves source");ChastityTests.equip(p);int xp=p.totalExperience;for(var orb:orbs){orb.playerTouch(p);orb.discard();}for(var item:items){item.setNoPickUpDelay();item.playerTouch(p);h.assertTrue(!item.isRemoved(),"actual loot blocked for wearer");item.discard();}h.assertTrue(p.totalExperience==xp,"actual death XP blocked for wearer");h.succeed();}finally{cow.discard();ChastityTests.close(p);}}
}
